arguments.command:
# Got the library! It's stripped though. Let me check dynamic symbols and try to get debug info
LIBPATH="/tmp/symbols/lib2.so"

# Check dynamic symbols - even stripped ELFs have these
nm -D "$LIBPATH" 2>/dev/null | wc -l

# Try to resolve addresses using dynamic symbol table
# The addresses we need:
# Thread main: 0x222098, 0x2241ac, 0x1abc80, 0x16de04
# Thread SGen: 0x2f4b20, 0x2f4c84  
# Thread Finalizer: 0x2c1a40

echo "=== Resolving with dynamic symbols ==="
for addr in 0x222098 0x2241ac 0x1abc80 0x16de04 0x2f4b20 0x2f4c84 0x2c1a40; do
  echo -n "$addr -> "
  # Use nm -D to get all dynamic symbols, then find the closest one before this address
  nm -D --defined-only "$LIBPATH" 2>/dev/null | awk -v target="$addr" '
    BEGIN { target_dec = strtonum(target); best_name = "??"; best_addr = 0; }
    { 
      addr_dec = strtonum("0x" $1);
      if (addr_dec <= target_dec && addr_dec > best_addr) {
        best_addr = addr_dec;
        best_name = $3;
      }
    }
    END { printf "%s+0x%x\n", best_name, target_dec - best_addr; }
  '
done

